using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "GainStarShardsAction", menuName = "Data/Battle/Battle Actions/GainStarShardsAction")]
public class GainStarShardsAction : BattleAction
{
	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ModifyGold(amount);
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
	}
}
